import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易阐真 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易阐真 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"zh/classics/chanzhen/049.md","filePath":"zh/classics/chanzhen/049.md"}'),s={name:"zh/classics/chanzhen/049.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：巽乎水而上水，井。井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘，井，未有功也。羸其瓶，是以凶也。</p></blockquote><h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>初六：井泥不食，旧井无禽。</p><p>九二：井谷射鲋，瓮敝漏。</p><p>九三：井渫不食，为我心恻。可用汲，王明，并受其福。</p><p>六四：井甃，无咎。</p><p>九五：井洌，寒泉食。</p><p>上六：井收勿幕，有孚元吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：木上有水，井。君子以劳民劝相。</p><p>井者，取其养人也。上坎水，下巽木，是木上有水也。水升于木上，木有水而滋润嫩脆，得其所养，井之象也。</p><p>君子有见于此，知民不可不养，既养不可不教。以是法水之流而不息，使民躬耕力作、饱食暖衣以养身；效木之丛而成林，教民知礼明义、和睦相助以养心。身心俱养，返朴归淳，忘其劳苦，一道同风，入于不识不知、顺帝之则之域矣。人之身，即国也；人之精神，即民也。整顿精神，日夜行道，即劳民也；迁善改过，去妄存诚，三家相见，四象和合，即劝相也。劳之所以忘其假，劝之所以修其真，假去真存，养之道尽矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>汔，音肸。繘副本，音橘。瓶，音平。谷，音育。鲋，音附。甕，乌贡反。渫，音牒。甃，音绉。冽，音列。幕，音莫。</p><p>井者，有本之水，养人不穷，取其养义。卦德上坎险，下巽入，渐进以通险，有险而能出，如木下水而出水，故谓井。此积功修德之卦，承上升卦而来。升者，巽进而顺行，所以增益其道德耳。道德增益，已巽进于无险之地，根本坚固，己无险而可以济人之险，于是积功修德，以己所养，养人之养，诚中达外，有益于彼，无伤于我，如井，改邑不改井，无丧无得，往来井井也。</p><p>夫修道者，养己已足，如井有水也。养己之后而养人，如改邑也。以自养者养人，如不改井也。养人必本于自养，养己如是，养人如是，如井无丧无得也。以养己者养人，人己皆得其所养，如往来井井也。若未到成道以后，强欲化人，则谓无本。无本之养，内无主宰，随人使用，逐风扬尘，未益于人，先失其己，亦如井中取水，汔至于井，繘副本 犹未至，井水羸其瓶，自取其凶。盖开导后学之事，在大道完成之后。大道完成，性命由我不由天，承先启后，可以有益于人，无伤于我。故六爻皆以自养为主也。</p><p>初六，性质本愚，不知求人以养己，乃无而为有，亦欲效高明者以养人，如旧井有泥无水，积污百端，禽亦不顾，焉能养人乎?此绝不知自养者也。</p><p>九二，正在养己之时，自养未足，即欲养人，无益于彼，先伤于我，如井谷外射，仅能养鲋，瓮敝水漏，浸润有限，其所以益于人者少，而其所自失者多。此养己未足者也。</p><p>九三，进于下体之上，养己已到可以养人之时，但近于险，未遇知音，限于不得养，如井水渫泛而无人食之也。然虽无人食，其道德崇高，望之者默相感化，是以为我心恻也。心恻者何?以其可用汲，望其有明眼，王公大人信而取用，则人人皆得法范，而受福无穷矣。此养己已足者也。</p><p>六四，居于险体，虽无养人之德，幸其柔而守正，能知自养，如井之凳以防险，内不伤而外不损，可无陷人之咎矣。此自知养己者也。</p><p>九五，阳居阴内，外虚内实，虚实如一，刚柔混合，大道完成，是谓有本之水，如井冽寒泉，所养深厚，取之不尽，用之不竭。此养己足而可养人者也。</p><p>上六，养己已到，如井功已收，可以勿幕井口，因人开导，自能有益于人，无伤于我。特以其吉已在于养己之初矣。此养人必本于养己者也。</p><p>然则养人之事，在成道以后，若未成道，未可养人。强欲养人，即有羸瓶之凶，养人者可不知先自养乎？</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
